import { Injectable } from '@angular/core';
import { CaseDetailResponce } from '../../../adminpanel/interfaces/casebuilder.interface';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class CasedetailService {
  private CaseDetail: CaseDetailResponce;
  constructor(private http: HttpClient,) { }


  async getCaseInfo(nCaseid: string): Promise<CaseDetailResponce> {
    if (this.CaseDetail && this.CaseDetail.nCaseid && this.CaseDetail.nCaseid == nCaseid) {
      return this.CaseDetail;
    } else {
      // return this.CaseDetail;
      try {
        var params = new HttpParams().set('nCaseid', nCaseid);
        const res: any = await firstValueFrom(
          this.http.get<CaseDetailResponce[]>(
            `${environment.cloudUrl}${environment.coreservice}/case/caseinfo`,
            { params: params }
          )
        );
        this.CaseDetail = res[0]
        return res;
      } catch (err) {
        return {};
      }
    }
  }

  resetState(): void {
    this.CaseDetail = null;
  }
}
